package pe.edu.upeu.pago.service;
import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import pe.edu.upeu.pago.client.*; import pe.edu.upeu.pago.dto.*; import pe.edu.upeu.pago.entity.*; import pe.edu.upeu.pago.exception.ResourceNotFoundException; import pe.edu.upeu.pago.repository.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class ReembolsoService {private final ReembolsoRepository repo;private final OrdenCompraRepository ordenRepo;private final MovimientoSaldoRepository movRepo;private final InscripcionClient inscripcion;private final NotificacionClient notificacion;private final MercadoPagoClient mercadoPago;@Value("${kido.pagos.dias-reembolso:7}")private long dias;@Value("${kido.pagos.progreso-max-reembolso:20}")private int max;
 @Transactional public ReembolsoResponse solicitar(ReembolsoRequest r){if(repo.findByOrdenId(r.ordenId()).isPresent())throw new IllegalStateException("Ya existe una solicitud para esta orden");OrdenCompra o=orden(r.ordenId());if(o.getEstado()!=OrdenCompra.EstadoOrden.APROBADA)throw new IllegalStateException("Solo una orden APROBADA puede reembolsarse");if(o.getFechaAprobacion()==null||LocalDateTime.now().isAfter(o.getFechaAprobacion().plusDays(dias)))throw new IllegalArgumentException("El plazo de reembolso de "+dias+" días venció");InscripcionDto i=inscripcion.buscar(o.getEstudianteId(),o.getCursoId());if(i.porcentajeProgreso()>max)throw new IllegalArgumentException("El progreso supera el "+max+"% permitido");Reembolso x=new Reembolso();x.setOrdenId(o.getId());x.setEstudianteId(o.getEstudianteId());x.setCursoId(o.getCursoId());x.setMonto(o.getMontoTotal());x.setMotivo(r.motivo());x.setPorcentajeProgreso(i.porcentajeProgreso());x.setEstado(Reembolso.EstadoReembolso.SOLICITADO);x.setFechaSolicitud(LocalDateTime.now());return map(repo.save(x));}
 @Transactional public ReembolsoResponse aprobar(Long id){Reembolso x=get(id);if(x.getEstado()!=Reembolso.EstadoReembolso.SOLICITADO)throw new IllegalStateException("El reembolso no está SOLICITADO");OrdenCompra o=orden(x.getOrdenId());if(o.getMercadoPagoPaymentId()!=null&&!o.getMercadoPagoPaymentId().startsWith("SIM-"))mercadoPago.reembolsar(o.getMercadoPagoPaymentId(),o.getMontoTotal(),"kido-refund-"+x.getId());inscripcion.revocar(o.getEstudianteId(),o.getCursoId());movRepo.findByOrdenIdAndTipo(o.getId(),MovimientoSaldo.TipoMovimiento.VENTA).ifPresent(m->{m.setEstado(MovimientoSaldo.EstadoMovimiento.REVERTIDO);movRepo.save(m);});o.setEstado(OrdenCompra.EstadoOrden.REEMBOLSADA);ordenRepo.save(o);x.setEstado(Reembolso.EstadoReembolso.APROBADO);x.setFechaProceso(LocalDateTime.now());notificacion.enviar(o.getEstudianteId(),"REEMBOLSO_APROBADO","Reembolso aprobado","Se aprobó el reembolso de S/ "+o.getMontoTotal()+".");notificacion.enviar(o.getDocenteId(),"VENTA_REEMBOLSADA","Venta reembolsada","La venta del curso "+o.getCursoTitulo()+" fue reembolsada y el saldo asociado se revirtió.");return map(repo.save(x));}
 @Transactional public ReembolsoResponse rechazar(Long id,String motivo){Reembolso x=get(id);if(x.getEstado()!=Reembolso.EstadoReembolso.SOLICITADO)throw new IllegalStateException("El reembolso ya fue procesado");x.setEstado(Reembolso.EstadoReembolso.RECHAZADO);x.setMotivoRechazo(motivo);x.setFechaProceso(LocalDateTime.now());return map(repo.save(x));}
 @Transactional(readOnly=true) public List<ReembolsoResponse> listar(){return repo.findAll().stream().map(this::map).toList();} private Reembolso get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Reembolso no encontrado: "+id));}private OrdenCompra orden(Long id){return ordenRepo.findById(id).orElseThrow(()->new ResourceNotFoundException("Orden no encontrada: "+id));}private ReembolsoResponse map(Reembolso x){return new ReembolsoResponse(x.getId(),x.getOrdenId(),x.getEstudianteId(),x.getCursoId(),x.getMonto(),x.getMotivo(),x.getPorcentajeProgreso(),x.getEstado().name(),x.getFechaSolicitud(),x.getFechaProceso(),x.getMotivoRechazo());}}
